def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A solid row identifies the color; in a row containing a partial
    # run of that color, mark the remainder with 1.
    solid_colors = {
        row[0] for row in grid
        if all(v == row[0] for v in row)
    }
    for r, row in enumerate(grid):
        for color in solid_colors:
            if color not in row or all(v == color for v in row):
                continue
            if all(v == color or v == row[0] for v in row):
                for c, v in enumerate(row):
                    if v != color:
                        out[r][c] = 1
                break
    return out
